/* ---------- Dynamische Header-Navigation: Zaehler + aktiver Zustand ----------
   Ersetzt fest eincodierte Zahlen im Header (die beim Kopieren einfroren
   und nie wieder aktualisiert wurden, siehe V1119-Fund: teils 3x zu
   niedrig) durch eine Live-Berechnung aus FR_POSTS -- exakt dieselbe
   Filterlogik wie frRenderCategoryPosts() (!!p.link && !p.draft), damit
   Header-Zaehler und tatsaechliche Kategorie-Seiten nie auseinanderlaufen
   koennen. Voraussetzung: Der Header selbst (_includes/header.html)
   enthaelt KEINE festen Zahlen oder is-active-Klassen mehr -- die HTML-
   Struktur ist fuer alle Seiten identisch, diese Funktion fuellt beim
   Laden auf. */
function frIsEnSafe(){
  try { return document.documentElement.getAttribute('lang') === 'en'; }
  catch(e){ return false; }
}
function frCatLabelDe(cat){
  const map = { "Finanzen":"Finanzen", "Minimalismus":"Lebensstil", "FIRE":"FIRE", "Technik":"Technik", "Bücher":"Bücher" };
  return map[cat] || cat;
}
function frUpdateNavCounts(){
  if(typeof FR_POSTS === 'undefined') return;

  const live = FR_POSTS.filter(p => !!p.link && !p.draft);

  const catTotals = {};
  live.forEach(p => { catTotals[p.cat] = (catTotals[p.cat] || 0) + 1; });

  const subcatTotals = {};
  live.forEach(p => { if(p.subcat) subcatTotals[p.subcat] = (subcatTotals[p.subcat] || 0) + 1; });

  if(typeof FR_CAT_PAGE !== 'undefined'){
    Object.keys(FR_CAT_PAGE).forEach(cat => {
      const page = FR_CAT_PAGE[cat];
      const total = catTotals[cat] || 0;
      document.querySelectorAll(`a.nav-drop-all[href="${page}"]`).forEach(el => {
        const en = frIsEnSafe();
        el.setAttribute('data-en', `All ${cat} posts (${total})`);
        el.textContent = en ? `All ${cat} posts (${total})` : `Alle ${frCatLabelDe(cat)}-Artikel (${total})`;
      });
    });
  }

  if(typeof FR_SUBCATS !== 'undefined'){
    Object.keys(FR_SUBCATS).forEach(mainCat => {
      FR_SUBCATS[mainCat].forEach(sub => {
        const count = subcatTotals[sub.key] || 0;
        document.querySelectorAll(`a.nav-sub-link[href="${sub.page}"] .nav-sub-count`).forEach(el => {
          el.textContent = `(${count})`;
        });
      });
    });
  }

  const currentFile = location.pathname.split('/').pop() || 'index.html';
  let activeCat = null, activeSubcatPage = null;

  if(typeof FR_SUBCATS !== 'undefined'){
    outer:
    for(const mainCat of Object.keys(FR_SUBCATS)){
      for(const sub of FR_SUBCATS[mainCat]){
        if(sub.page === currentFile){
          activeCat = mainCat;
          activeSubcatPage = sub.page;
          break outer;
        }
      }
    }
  }
  if(!activeCat){
    const post = FR_POSTS.find(p => p.link === currentFile);
    if(post){
      activeCat = post.cat;
      if(post.subcat && typeof FR_SUBCATS !== 'undefined' && FR_SUBCATS[post.cat]){
        const sub = FR_SUBCATS[post.cat].find(s => s.key === post.subcat);
        if(sub) activeSubcatPage = sub.page;
      }
    }
  }

  if(activeSubcatPage){
    // Robuster als ueber FR_CAT_PAGE zu gehen: das umschliessende .nav-drop
    // des aktiven Unterkategorie-Links direkt aktivieren -- funktioniert
    // auch dann korrekt, wenn mehrere Hauptkategorien unter einem
    // gemeinsamen Dropdown gruppiert sind (z.B. FIRE + Minimalismus unter
    // "Lebensstil"/kat-lebensstil.html), unabhaengig davon, ob FR_CAT_PAGE
    // exakt denselben Zielnamen verwendet.
    document.querySelectorAll(`a.nav-sub-link[href="${activeSubcatPage}"]`).forEach(el => {
      el.classList.add('is-active');
      const toggle = el.closest('.nav-drop')?.querySelector('.nav-drop-toggle');
      if(toggle) toggle.classList.add('is-active');
    });
  } else if(activeCat && typeof FR_CAT_PAGE !== 'undefined'){
    // Fallback nur fuer Faelle ohne Unterkategorie-Treffer (z.B. FIRE hat
    // aktuell keine eigenen Unterkategorien in FR_SUBCATS).
    const catPage = FR_CAT_PAGE[activeCat];
    if(catPage){
      document.querySelectorAll(`a.nav-drop-all[href="${catPage}"]`).forEach(el => {
        const toggle = el.closest('.nav-drop-panel')?.previousElementSibling;
        if(toggle && toggle.classList.contains('nav-drop-toggle')){
          toggle.classList.add('is-active');
        }
      });
    }
  }

  // Separater "CALC"-Schnellzugriff (.nav-rechner-link): aktiv auf
  // rechner.html selbst UND allen rechner-*.html-Tool-Seiten -- diese
  // sind keine Blog-Artikel und stehen nicht in FR_POSTS/FR_SUBCATS,
  // daher eigene, einfache Dateiname-basierte Erkennung statt der
  // Kategorie-Logik oben. .ladder-quick-link (zeigt ebenfalls auf
  // rechner.html) bleibt bewusst unangetastet -- wird im Original nie
  // aktiviert, nur nav-rechner-link.
  if(currentFile === 'rechner.html' || /^rechner-/.test(currentFile)){
    document.querySelectorAll('a.nav-rechner-link').forEach(el => el.classList.add('is-active'));
  }
}
document.addEventListener('DOMContentLoaded', frUpdateNavCounts);
window.frPageRecomputers = window.frPageRecomputers || [];
window.frPageRecomputers.push(frUpdateNavCounts);

function frSubcatLabel(cat, key){
  const list = FR_SUBCATS[cat] || [];
  const hit = list.find(s => s.key === key);
  if(!hit) return '';
  return frIsEn() ? hit.labelEn : hit.label;
}

/* Label für die Kategorie-Kennzeichnung auf "Alle"-Übersichtsseiten:
   bevorzugt die Unterkategorie (z.B. "ETF & Sparplan"), fällt auf die
   Hauptkategorie zurück, wenn der Beitrag keiner Unterkategorie
   zugeordnet ist (z.B. FIRE, das keine Unterkategorien hat). */
/* GCAT-Anzeigenamen — dieselben deutschen/englischen Labels wie im
   Glossar-Dropdown (glossar.html), damit beide Systeme konsistent
   wirken. */
const FR_GCAT_LABELS = {
  wirtschaft:        { de:"Wirtschaft",       en:"Economy" },
  eu_recht:          { de:"EU-Recht",         en:"EU Law" },
  boerse:            { de:"Börse",            en:"Stock Market" },
  investment:        { de:"Investment",       en:"Investing" },
  crypto:            { de:"Krypto",           en:"Crypto" },
  karriere_learning: { de:"Karriere & Lernen",en:"Career & Learning" },
  absicherung:       { de:"Absicherung",      en:"Insurance" },
  allgemein_tech:    { de:"Tech",             en:"Tech" },
  allgemein:         { de:"Allgemein",        en:"General" },
};
function frGcatLabel(gcat){
  const entry = FR_GCAT_LABELS[gcat];
  if(!entry) return '';
  return frIsEn() ? entry.en : entry.de;
}

function frItemTagLabel(p){
  return frSubcatLabel(p.cat, p.subcat) || frCat(p.cat);
}

function frFormatDate(iso){
  const d = new Date(iso);
  return d.toLocaleDateString('de-DE', { day:'2-digit', month:'2-digit', year:'numeric' });
}

/* =========================================================
   SICHERHEIT: Escaping für alle Daten, die per innerHTML
   in die Seite geschrieben werden.
   ---------------------------------------------------------
   Wichtig für FR_TARIFE: dieser Block wird automatisch aus
   einer FREMDEN Website erzeugt (tools/update_tarife.py).
   Ohne Escaping könnte ein manipulierter Anbietername dort
   Code auf deiner Seite ausführen (Stored XSS).
   Regel: jeder ${...}-Wert in einem innerHTML-Template läuft
   durch frEsc(), jede URL zusätzlich durch frSafeUrl().
   ========================================================= */
const FR_HTML_ESC = { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' };

function frEsc(wert){
  return String(wert == null ? '' : wert).replace(/[&<>"']/g, c => FR_HTML_ESC[c]);
}

/* Lässt nur unbedenkliche Ziele durch. Blockt javascript:, data:, vbscript: usw. */
function frSafeUrl(url){
  const u = String(url == null ? '' : url).trim();
  if(!u) return '#';
  if(/^(https?:\/\/|mailto:|tel:|#|\/|\.\/|\.\.\/)/i.test(u)) return u;
  // Relative .html-Dateien im gleichen Verzeichnis erlauben
  if(/^[a-zA-Z0-9_-]+\.html(#[a-zA-Z0-9_-]*)?$/.test(u)) return u;
  console.warn('[Finanzritual] Unsicheres Link-Ziel blockiert:', u);
  return '#';
}

/* ---------- Tag-Cloud: Häufigkeit automatisch aus FR_POSTS berechnen ---------- */
function frBuildTagCloud(targetId, moreBtnId, pageSize=20){
  const el = document.getElementById(targetId);
  let moreBtn = moreBtnId ? document.getElementById(moreBtnId) : null;
  if(!el) return;
  const counts = {};
  FR_POSTS.filter(p => !p.draft).forEach(p => p.tags.forEach(t => { counts[t] = (counts[t]||0) + 1; }));
  const entries = Object.entries(counts).sort((a,b) => b[1]-a[1]);
  const max = Math.max(...entries.map(e => e[1]));
  const min = Math.min(...entries.map(e => e[1]));
  const minSize = 0.85, maxSize = 2.2;

  el.innerHTML = '';
  /* Klon ohne alte Klick-Listener - wichtig, damit ein erneuter Aufruf
     (z. B. beim Sprachwechsel) nicht mehrfach "Mehr laden" auslöst. */
  if(moreBtn){
    const clone = moreBtn.cloneNode(true);
    moreBtn.parentNode.replaceChild(clone, moreBtn);
    moreBtn = clone;
  }
  let shown = 0;

  function renderNext(){
    const slice = moreBtn ? entries.slice(shown, shown+pageSize) : entries;
    slice.forEach(([tag,count]) => {
      const size = max === min ? (minSize+maxSize)/2
        : minSize + (count-min)/(max-min) * (maxSize-minSize);
      const a = document.createElement('a');
      a.href = frSafeUrl(hrefForTag(tag));
      a.style.fontSize = size.toFixed(2) + 'rem';
      a.textContent = frTag(tag);
      a.title = frIsEn()
        ? count + (count===1 ? ' post' : ' posts')
        : count + (count===1 ? ' Beitrag' : ' Beiträge');
      el.appendChild(a);
    });
    shown += slice.length;
    if(moreBtn){ moreBtn.style.display = shown >= entries.length ? 'none' : 'inline-flex'; }
  }
  renderNext();
  if(moreBtn){ moreBtn.addEventListener('click', renderNext); }
}
/* Verlinkt ein Tag auf die passendste Seite: Unterkategorie-Seite, falls der
   erste Treffer eine hat, sonst die Hauptkategorie-Seite. */
function hrefForTag(tag){
  const hit = FR_POSTS.find(p => p.tags.includes(tag) && !p.draft);
  if(!hit) return 'kat-finanzen.html';
  const subList = FR_SUBCATS[hit.cat] || [];
  const subHit = hit.subcat && subList.find(s => s.key === hit.subcat);
  return subHit ? subHit.page : (FR_CAT_PAGE[hit.cat] || 'kat-finanzen.html');
}

/* ---------- Startseiten-Feed (neueste zuerst, "Mehr laden") ---------- */
function frBuildFeed(targetId, moreBtnId, pageSize=5){
  const el = document.getElementById(targetId);
  let moreBtn = document.getElementById(moreBtnId);
  if(!el) return;
  el.innerHTML = '';
  /* Klon ohne alte Klick-Listener - wichtig, damit ein erneuter Aufruf
     (z. B. beim Sprachwechsel) nicht mehrfach "Mehr laden" auslöst. */
  if(moreBtn){
    const clone = moreBtn.cloneNode(true);
    moreBtn.parentNode.replaceChild(clone, moreBtn);
    moreBtn = clone;
  }
  const sorted = [...FR_POSTS].filter(p => !p.draft).sort((a,b) => new Date(b.date) - new Date(a.date));
  let shown = 0;

  function renderNext(){
    const slice = sorted.slice(shown, shown+pageSize);
    slice.forEach(p => {
      const item = document.createElement('article');
      item.className = 'feed-item';
      if(p.gcat) item.setAttribute('data-gcat', p.gcat);
      const href = frSafeUrl(p.link || FR_CAT_PAGE[p.cat] || 'kat-finanzen.html');
      item.innerHTML = `
        <time datetime="${frEsc(p.date)}">${frEsc(frFormatDate(p.date))}</time>
        <div>
          <span class="feed-cat">${frEsc(p.gcat ? frGcatLabel(p.gcat) : frCat(p.cat))}</span>
          <h3><a href="${frEsc(href)}">${frEsc(frTitle(p))}</a></h3>
          <p>${frEsc(frExcerpt(p))}</p>
        </div>`;
      el.appendChild(item);
    });
    shown += slice.length;
    if(moreBtn){ moreBtn.style.display = shown >= sorted.length ? 'none' : 'inline-flex'; }
  }
  renderNext();
  if(moreBtn){ moreBtn.addEventListener('click', renderNext); }
}

