function frApplySnippets(){
  var en = document.documentElement.getAttribute('lang') === 'en';
  document.querySelectorAll('[data-fr-snippet]').forEach(function(el){
    var key = el.getAttribute('data-fr-snippet');
    if(Object.prototype.hasOwnProperty.call(FR_SNIPPETS, key)){
      el.innerHTML = en ? FR_SNIPPETS[key].en : FR_SNIPPETS[key].de;
    }
  });
}
if(Array.isArray(window.frPageRecomputers)){
  window.frPageRecomputers.push(frApplySnippets);
} else {
  window.frPageRecomputers = [frApplySnippets];
}

