/* Fuellt alle [data-fr-const]-Elemente mit dem passenden Wert aus
   FR_CONFIG. Laeuft beim Laden UND nochmal nach jedem Sprachwechsel
   (Werte sind sprachneutral, aber die Funktion ist billig genug,
   um sie im selben Rhythmus wie das Glossar einfach mitlaufen zu
   lassen). Unbekannte Schluessel werden bewusst ignoriert statt
   einen Fehler zu werfen -- ein Tippfehler im Artikel soll die Seite
   nie zum Absturz bringen, hoechstens eine leere Stelle hinterlassen. */
function frInitConstants(){
  document.querySelectorAll('[data-fr-const]').forEach(el => {
    const key = el.getAttribute('data-fr-const');
    if(Object.prototype.hasOwnProperty.call(FR_CONFIG, key)){
      el.textContent = FR_CONFIG[key];
    }
  });
}

/* ================================================================
   AUTOMATISCH VERWANDTE ARTIKEL
   ----------------------------------------------------------------
   Loest ein wachsendes Problem bei > 100 Artikeln: von Hand
   gepflegte "Verwandt"-Boxen veralten zwangslaeufig, sobald neue
   Artikel dazukommen -- niemand denkt daran, alte Beitraege
   rueckwirkend mit neuen zu verlinken. Diese Funktion braucht keine
   Pflege: sie laeuft bei jedem Seitenaufruf automatisch, findet die
   aktuelle Seite in FR_POSTS wieder und zeigt die passendsten
   anderen Artikel an -- rueckwirkend fuer ALLE Artikel, sobald ein
   neuer in FR_POSTS auftaucht, ohne dass irgendeine Datei angefasst
   werden muss. Ergaenzt (ersetzt nicht) die weiterhin von Hand
   gepflegten "Weiter"-Links fuer bewusste Lese-Reihenfolgen
   innerhalb einer Artikel-Serie. */
function frInitRelatedArticles(){
  const container = document.querySelector('article.legal .wrap, article .wrap, article.y-article');
  if(!container) return;
  if(typeof FR_POSTS === 'undefined') return;

  // Bereits vorhandene automatische Box zuerst entfernen (Selbstheilung
  // bei Sprachwechsel, damit nicht doppelt gerendert wird).
  const old = container.querySelector('.fr-related-auto');
  if(old) old.remove();

  const path = location.pathname.split('/').pop();
  const current = FR_POSTS.find(p => p.link === path);
  if(!current) return; // keine Artikelseite oder nicht in FR_POSTS gelistet

  // Bereits im Artikel vorhandene Links sammeln (z.B. aus handverlesenen
  // "Verwandt"/"Weiter"-Boxen) -- diese sollen in der automatischen Box
  // nicht ein zweites Mal auftauchen. Einfacher, robuster Ansatz statt
  // die verschiedenen handverlesenen Box-Varianten einzeln zu erkennen:
  // wenn der Link schon irgendwo im Artikeltext als <a href> steht,
  // gilt er als "schon gezeigt", egal in welcher Box.
  const alreadyLinked = new Set(
    [...container.querySelectorAll('a[href]')]
      .map(a => a.getAttribute('href').split('/').pop())
  );

  const isEnglish = document.documentElement.getAttribute('lang') === 'en';
  const currentTags = new Set((current.tags || []).map(t => t.toLowerCase()));

  // Drittes Aehnlichkeits-Signal (V866, Nutzer-Vorschlag): geteilte
  // Glossarbegriffe im Artikeltext. FR_ARTICLE_TERMS wird von
  // generate_article_glossary_terms.py vorberechnet (haeufige, generische
  // Begriffe wie "Rendite" sind dort bereits herausgefiltert, siehe
  // Skript-Kommentar) -- ein geteilter Begriff ist deshalb ein starkes
  // Signal fuer echte inhaltliche Naehe, nicht nur gleiche Oberkategorie.
  const hasTermData = typeof FR_ARTICLE_TERMS !== 'undefined' && typeof FR_TERM_CATEGORIES !== 'undefined';
  const currentTerms = hasTermData ? new Set(FR_ARTICLE_TERMS[current.link] || []) : new Set();
  const currentTermCats = new Set([...currentTerms].map(t => FR_TERM_CATEGORIES[t]).filter(Boolean));

  const scored = FR_POSTS
    .filter(p => p.link !== current.link && p.link && !alreadyLinked.has(p.link) && !p.draft)
    .map(p => {
      let score = 0;
      if(p.subcat && p.subcat === current.subcat) score += 10;
      else if(p.cat === current.cat) score += 1;
      (p.tags || []).forEach(t => { if(currentTags.has(t.toLowerCase())) score += 3; });

      if(hasTermData && currentTerms.size){
        const otherTerms = FR_ARTICLE_TERMS[p.link] || [];
        let sharedCount = 0;
        let sharedSameCat = 0;
        otherTerms.forEach(function(t){
          if(currentTerms.has(t)){
            sharedCount += 1;
            if(currentTermCats.has(FR_TERM_CATEGORIES[t])) sharedSameCat += 1;
          }
        });
        // Ab 3 geteilten Begriffen (Nutzer-Schwelle) deutlicher Bonus,
        // jeder einzelne geteilte Begriff zaehlt zusaetzlich leicht --
        // so wirkt auch 1-2 gemeinsame Begriffe leicht mit, ohne die
        // Tag-/Subkategorie-Signale zu dominieren.
        score += sharedCount * 2;
        if(sharedCount >= 3) score += 6;
        // Kleiner Zusatzbonus, wenn die geteilten Begriffe auch aus
        // derselben Glossar-Kategorie stammen (nicht nur zufaellig beide
        // im Text vorkommen, sondern thematisch eng verwandt).
        if(sharedSameCat >= 2) score += 2;
      }

      return { post: p, score };
    })
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score || new Date(b.post.date) - new Date(a.post.date))
    .slice(0, 4);

  // Bei zu wenig thematischer Naehe lieber gar keine Box zeigen als
  // eine duenne, kaum relevante Liste.
  if(scored.length < 2) return;

  const box = document.createElement('div');
  box.className = 'fr-related-auto';
  const label = document.createElement('p');
  label.className = 'fr-related-auto-label';
  label.textContent = isEnglish ? 'Similar articles' : 'Ähnliche Artikel';
  box.appendChild(label);
  const ul = document.createElement('ul');
  ul.className = 'fr-related-auto-list';
  scored.forEach(({ post }) => {
    const li = document.createElement('li');
    const a = document.createElement('a');
    a.href = post.link;
    a.textContent = '→ ' + (isEnglish && post.titleEn ? post.titleEn : post.title);
    li.appendChild(a);
    ul.appendChild(li);
  });
  box.appendChild(ul);

  container.appendChild(box);
}

function frAutoLinkGlossary(){
  const container = document.querySelector('article.legal .wrap, article .wrap, article.y-article');
  if(!container) return;

  // Selbstheilung: eigene, frueher automatisch eingefuegte Tooltips zuerst
  // wieder entfernen (reinen Text wiederherstellen), bevor neu gescannt
  // wird. Notwendig, weil nicht jede Textstelle ein data-en-Attribut hat
  // (z.B. reine Zahlenzellen in Tabellen) -- ohne das wuerde die
  // Sprachumschaltung eine automatisch eingefuegte deutsche Erklaerung
  // im Englischen stehen lassen, statt sie durch die englische zu
  // ersetzen. Von Hand gebaute Tooltips (ESG, Spread) tragen dieses
  // Attribut nicht und bleiben unangetastet.
  container.querySelectorAll('.term-tip[data-auto-glossary="true"]').forEach(function(el){
    // IMPORTANT: textContent of the tooltip also contains the popup text.
    // Using el.textContent here used to leak the complete glossary entry
    // back into the article on every DE/EN or Einfach/Schwer switch.
    // Keep only the original matched term. The data attribute is written
    // when the tooltip is created and is therefore the safe source.
    const term = el.getAttribute('data-glossary-term') ||
                 (el.firstChild && el.firstChild.nodeType === Node.TEXT_NODE
                   ? el.firstChild.nodeValue : '');
    el.replaceWith(document.createTextNode(term));
  });
  container.normalize(); // benachbarte Text-Knoten wieder zusammenfuehren

  const isEnglish = document.documentElement.getAttribute('lang') === 'en';
  const dict = isEnglish ? FR_GLOSSARY_EN : FR_GLOSSARY;
  // Auf JugendBASISbildung-Seiten (erkennbar am y-article-Container) wird,
  // wenn vorhanden, das einfachere "youth"/"youthEn"-Feld bevorzugt --
  // sonst faellt es automatisch auf die normale de/en-Erklaerung zurueck.
  // Kein zweites Glossar, nur ein optionales Zusatzfeld pro Begriff.
  const isYouthPage = !!document.querySelector('article.y-article');
  const defKey = isYouthPage
    ? (isEnglish ? 'youthEn' : 'youth')
    : (isEnglish ? 'en' : 'de');
  const glossarLabel = isEnglish ? 'Glossary' : 'Glossar';
  const linkText = isEnglish ? 'Full glossary entry →' : 'Ganzer Glossar-Eintrag →';
  const ariaPrefix = isEnglish ? 'Show glossary explanation for ' : 'Begriffserklärung ';
  const ariaSuffix = isEnglish ? '' : ' anzeigen';

  // Begriffe nach Laenge absteigend sortieren, damit z.B. "EBITDA" vor
  // "EBIT" geprueft wird und nicht faelschlich in zwei Teile zerlegt wird.
  const terms = Object.keys(dict).sort((a, b) => b.length - a.length);

  // Begriffe, die auf dieser Seite (egal ob von Hand oder automatisch)
  // bereits ein Tooltip haben, nicht doppelt versehen. Case-insensitiv
  // verglichen, damit ein deutscher Begriff nicht doppelt mit seiner
  // englischen Entsprechung kollidiert und umgekehrt.
  const already = new Set();
  document.querySelectorAll('.term-tip').forEach(function(el){
    const txt = (el.getAttribute('data-glossary-term') || el.textContent || '').trim().toLowerCase();
    if(txt) already.add(txt);
  });

  const escapedTerms = terms.map(function(term){
    return term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  });
  const combinedPattern = isEnglish
    ? new RegExp('\\b(' + escapedTerms.join('|') + ')s?\\b', 'gi')
    : new RegExp('\\b(' + escapedTerms.join('|') + ')\\b', 'g');

  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, {
    acceptNode: function(node){
      const p = node.parentElement;
      if(!p) return NodeFilter.FILTER_REJECT;
      if(p.closest('a, .term-tip, script, style, h1, h2, h3, .eyebrow, .breadcrumb, th, svg, [class$="-label"], [class*="-label "]')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  const candidates = [];
  let node;
  while((node = walker.nextNode())){
    combinedPattern.lastIndex = 0;
    let m;
    // Schleife statt einmaligem exec(): findet ALLE Treffer im selben
    // Textknoten, nicht nur den ersten. Vorher brach ein Absatz mit
    // zwei Glossar-Begriffen (z.B. "...als Freelancer... eine
    // Privatentnahme...") die Verlinkung fuer den zweiten Begriff
    // stillschweigend ab, da combinedPattern.exec() nur einmal
    // aufgerufen wurde. Der Regex hat das "g"-Flag, exec() setzt
    // combinedPattern.lastIndex nach jedem Treffer automatisch weiter.
    while((m = combinedPattern.exec(node.nodeValue))){
      const key = m[1].toLowerCase();
      if(!already.has(key)){
        candidates.push({ node: node, fullMatch: m[0], lookupKey: isEnglish ? key : m[1], index: m.index });
        already.add(key); // pro Begriff weiterhin nur die erste Fundstelle auf der Seite
      }
    }
  }

  // Nach Textknoten gruppieren, damit mehrere Treffer im selben Absatz
  // korrekt nacheinander verarbeitet werden -- ein einzelner Knoten
  // kann jetzt mehrere Kandidaten haben, die sich sonst gegenseitig die
  // Text-Indizes verschieben wuerden.
  const byNode = new Map();
  candidates.forEach(function(c){
    if(!dict[c.lookupKey]) return;
    if(!byNode.has(c.node)) byNode.set(c.node, []);
    byNode.get(c.node).push(c);
  });

  byNode.forEach(function(nodeCandidates, textNode){
    nodeCandidates.sort(function(a, b){ return a.index - b.index; });
    const fullText = textNode.nodeValue;
    const parent = textNode.parentNode;
    let cursor = 0;
    const pieces = [];

    nodeCandidates.forEach(function(c){
      if(c.index < cursor) return; // ueberlappender Treffer, ueberspringen
      pieces.push({ type:'text', value: fullText.slice(cursor, c.index) });
      pieces.push({ type:'term', c: c });
      cursor = c.index + c.fullMatch.length;
    });
    pieces.push({ type:'text', value: fullText.slice(cursor) });

    pieces.forEach(function(piece){
      if(piece.type === 'text'){
        if(piece.value) parent.insertBefore(document.createTextNode(piece.value), textNode);
        return;
      }
      const c = piece.c;
      const info = dict[c.lookupKey];
      const wrapper = document.createElement('span');
      wrapper.className = 'term-tip';
      wrapper.tabIndex = 0;
      wrapper.setAttribute('role', 'button');
      wrapper.setAttribute('data-glossary-term', c.fullMatch);
      wrapper.setAttribute('data-auto-glossary', 'true');
      if (info.cat) wrapper.setAttribute('data-cat', info.cat);
      wrapper.setAttribute('aria-label', ariaPrefix + c.fullMatch + ariaSuffix);
      wrapper.textContent = c.fullMatch;

      const popup = document.createElement('span');
      popup.className = 'term-tip-popup';
      popup.setAttribute('role', 'tooltip');
      const label = document.createElement('span');
      label.className = 'term-tip-label';
      label.textContent = glossarLabel;
      popup.appendChild(label);
      var popupText = info[defKey] || info[isEnglish ? 'en' : 'de'];
      popup.appendChild(document.createTextNode(popupText + ' '));
      const link = document.createElement('a');
      link.href = 'glossar.html#' + info.id;
      link.textContent = linkText;
      popup.appendChild(link);
      wrapper.appendChild(popup);

      parent.insertBefore(wrapper, textNode);
    });

    parent.removeChild(textNode);
  });
}

/* ==========================================================================
   DEV-MODE: Glossar-Signifikanz sichtbar machen (?devmode=glossary)
   --------------------------------------------------------------------------
   Rein internes QA-Werkzeug, kein Nutzer-Feature. Zeigt auf der aktuellen
   Seite, welche automatisch verlinkten Glossarbegriffe als "generisch"
   gelten (breit gestreut UND haeufig im Volltext -- siehe
   _einrichtung/tools/analyze_glossary_link_significance.js) und welche
   als "signifikant" (spezifischer Fachbegriff) gewertet werden.

   WICHTIG: Die Generisch-Liste kann NICHT live im Browser berechnet
   werden -- eine einzelne Seite kennt nicht den Volltext der anderen
   307 Artikel. Sie wird stattdessen offline per Playwright-Skript
   projektweit ermittelt und hier als statische Liste eingebettet.
   Bei neuen Artikeln/Begriffen das Skript erneut laufen lassen und
   diese Liste von Hand nachziehen -- kein automatischer Rebuild.

   Stand der Analyse: 23.08.2026, Schwellen: Dokumenthaeufigkeit > 15 %
   UND Rohvorkommen im Volltext > 80. Ergab 5 generische Begriffe aus
   1.011 insgesamt verlinkten Begriffen ueber 308 Artikel.
   ========================================================================== */
const FR_GENERIC_GLOSSARY_TERMS = new Set(['etf', 'einkommen', 'rendite', 'depot', 'risiko']);

function frInitDevModeGlossary(){
  const params = new URLSearchParams(location.search);
  if(params.get('devmode') !== 'glossary') return; // billige Pruefung zuerst, keine Kosten fuer normale Besucher

  // Idempotenz: bei jedem erneuten Durchlauf (z.B. Sprachwechsel) zuerst ein
  // evtl. schon vorhandenes altes Panel entfernen, statt ein zweites daneben
  // anzuhaengen. Die Highlight-Klassen auf den Tooltips selbst muessen nicht
  // separat bereinigt werden: frAutoLinkGlossary() baut die .term-tip-Elemente
  // bei jedem Durchlauf komplett neu auf, alte Klassen verschwinden mit ihnen.
  const existingPanel = document.querySelector('.fr-devmode-panel');
  if(existingPanel) existingPanel.remove();

  const termTips = document.querySelectorAll('.term-tip[data-auto-glossary="true"]');
  let genericCount = 0, significantCount = 0;
  const genericFound = [], significantFound = [];

  termTips.forEach(el => {
    const term = el.getAttribute('data-glossary-term') || el.textContent.trim();
    const isGeneric = FR_GENERIC_GLOSSARY_TERMS.has(term.toLowerCase());
    el.classList.add(isGeneric ? 'fr-devmode-generic' : 'fr-devmode-significant');
    if(isGeneric){ genericCount++; genericFound.push(term); }
    else { significantCount++; significantFound.push(term); }
  });

  const panel = document.createElement('div');
  panel.className = 'fr-devmode-panel';
  panel.innerHTML =
    '<strong>🛠 Dev-Mode: Glossar-Signifikanz</strong>' +
    '<div class="fr-devmode-row"><span>Auto-Links gesamt</span><strong>' + termTips.length + '</strong></div>' +
    '<div class="fr-devmode-row"><span style="color:#238636">Signifikant</span><strong>' + significantCount + '</strong></div>' +
    '<div class="fr-devmode-row"><span style="color:#e2694b">Generisch</span><strong>' + genericCount + '</strong></div>' +
    '<div class="fr-devmode-term-list">' +
      genericFound.map(t => '<span style="background:rgba(226,105,75,.25);color:#e2694b">' + t + '</span>').join('') +
      significantFound.map(t => '<span style="background:rgba(35,134,54,.2);color:#8ee6a8">' + t + '</span>').join('') +
    '</div>';
  document.body.appendChild(panel);
}

document.addEventListener('DOMContentLoaded', function(){
  frInitConstants();
  frAutoLinkGlossary();
  frInitRelatedArticles();
  frInitDevModeGlossary();
});
if(Array.isArray(window.frPageRecomputers)){
  window.frPageRecomputers.push(frAutoLinkGlossary);
} else {
  window.frPageRecomputers = [frAutoLinkGlossary];
}
// WICHTIG: erst NACH frAutoLinkGlossary registrieren, sonst laeuft der
// Dev-Mode-Scan beim Sprachwechsel auf den alten, noch nicht neu erzeugten
// Tooltip-Elementen und zeigt falsche Zahlen.
if(Array.isArray(window.frPageRecomputers)){
  window.frPageRecomputers.push(frInitDevModeGlossary);
} else {
  window.frPageRecomputers = [frInitDevModeGlossary];
}

/* ==========================================================================
   VIDEO-EMBED: ID automatisch aus dem fr-video-id-Meta-Tag uebernehmen
   --------------------------------------------------------------------------
   Ein .fr-video-embed-Container im Artikel bekommt seine data-fr-video-id
   automatisch vom <meta name="fr-video-id"> im <head> zugewiesen -- die ID
   muss dadurch nur an EINER Stelle (dem Meta-Tag) gepflegt werden, statt sie
   zusaetzlich von Hand in jeden Video-Block einzutragen (und beide Stellen
   synchron zu halten). Rein informativ/fuer die eigene Verwaltung gedacht,
   kein sichtbares oder funktionales Element fuer Leser.
   ========================================================================== */
function frLinkVideoEmbedToArticleId(){
  const meta = document.querySelector('meta[name="fr-video-id"]');
  if(!meta) return;
  const id = meta.getAttribute('content');
  if(!id) return;
  document.querySelectorAll('.fr-video-embed').forEach(el => {
    el.setAttribute('data-fr-video-id', id);
  });
}
document.addEventListener('DOMContentLoaded', frLinkVideoEmbedToArticleId);

/* =========================================================
   PROZENT-FORMATIERUNG: kein Leerzeichen vor "%"
   ---------------------------------------------------------
   Nutzer-Vorgabe: "10,3 %" bricht bei vergroesserter Schrift
   das % auf eine eigene Zeile um -- schlecht lesbar. Ab jetzt
   global "10,3%" (kein Leerzeichen), automatisch fuer JEDEN
   Artikel, alt wie neu -- ohne die Quelldateien einzeln
   anzufassen. Gilt bewusst nur fuer %, nicht fuer € (dort ist
   das Leerzeichen deutsche Standardkonvention und das Problem
   laut Nutzer ohnehin seltener). */
function frFixPercentSpacing(){
  const container = document.querySelector('article.legal .wrap, article .wrap, article.y-article');
  if(!container) return;

  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, {
    acceptNode: function(node){
      const p = node.parentElement;
      if(!p) return NodeFilter.FILTER_REJECT;
      if(p.closest('script, style')) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  const pattern = /(\d[\d.,]*)[ \t\u00A0]+%/g;
  let node;
  while((node = walker.nextNode())){
    if(pattern.test(node.nodeValue)){
      pattern.lastIndex = 0;
      node.nodeValue = node.nodeValue.replace(pattern, '$1%');
    }
  }
}

document.addEventListener('DOMContentLoaded', function(){
  frFixPercentSpacing();
});
if(Array.isArray(window.frPageRecomputers)){
  window.frPageRecomputers.push(frFixPercentSpacing);
} else {
  window.frPageRecomputers = [frFixPercentSpacing];
}

/* ---------- Schnee-Animation im Header zur Weihnachtszeit ----------
   Aktiv 15.12. bis 10.1., NUR im Dunkelmodus sichtbar (weisse Flocken
   auf hellem Hintergrund waeren kaum erkennbar). Im Hellmodus laeuft
   dieselbe Pruef-Logik durch, tut aber bewusst nichts ("leeres Gif
   ohne Aktion") -- so bleibt die Systematik (Datum pruefen -> Modus
   pruefen -> ggf. anzeigen) fuer beide Faelle identisch, auch wenn nur
   eine Haelfte optisch etwas bewirkt. Leichtgewichtiges Canvas statt
   einer echten GIF-Datei: kein zusaetzlicher Bilder-Download, reagiert
   sofort auf Farbmodus-Wechsel, respektiert reduzierte Bewegung. */
(function frHeaderSnow(){
  function isChristmasWindow(){
    var today = new Date();
    var month = today.getMonth() + 1;
    var day = today.getDate();
    return (month === 12 && day >= 15) || (month === 1 && day <= 10);
  }

  var canvas = null, ctx = null, flakes = [], rafId = null;
  var reducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function createCanvas(header){
    canvas = document.createElement('canvas');
    canvas.setAttribute('aria-hidden', 'true');
    canvas.style.cssText = 'position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:1;';
    header.style.position = header.style.position || 'sticky';
    header.appendChild(canvas);
    resize();
    window.addEventListener('resize', resize);
  }

  function resize(){
    if(!canvas) return;
    var header = canvas.parentElement;
    canvas.width = header.clientWidth;
    canvas.height = header.clientHeight;
  }

  function spawnFlakes(){
    var count = Math.max(14, Math.min(28, Math.floor(canvas.width / 40)));
    flakes = [];
    for(var i = 0; i < count; i++){
      flakes.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        r: 1.2 + Math.random() * 2.2,
        speed: 0.25 + Math.random() * 0.5,
        drift: (Math.random() - 0.5) * 0.4,
        opacity: 0.35 + Math.random() * 0.45,
      });
    }
  }

  function tick(){
    if(!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for(var i = 0; i < flakes.length; i++){
      var f = flakes[i];
      f.y += f.speed;
      f.x += f.drift;
      if(f.y > canvas.height){ f.y = -4; f.x = Math.random() * canvas.width; }
      if(f.x > canvas.width) f.x = 0;
      if(f.x < 0) f.x = canvas.width;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.shadowColor = 'rgba(255,255,255,.9)';
      ctx.shadowBlur = f.r * 3;
      ctx.fillStyle = 'rgba(255,255,255,' + f.opacity + ')';
      ctx.fill();
    }
    rafId = requestAnimationFrame(tick);
  }

  function startSnow(){
    if(rafId) return; // laeuft schon
    var header = document.querySelector('header.site');
    if(!header) return;
    if(!canvas) createCanvas(header);
    ctx = canvas.getContext('2d');
    resize();
    spawnFlakes();
    if(!reducedMotion){
      rafId = requestAnimationFrame(tick);
    } else {
      // Statisches Einzelbild statt Dauerschleife, respektiert die
      // Systemeinstellung fuer reduzierte Bewegung.
      tick_once();
    }
  }
  function tick_once(){
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    flakes.forEach(function(f){
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.shadowColor = 'rgba(255,255,255,.9)';
      ctx.shadowBlur = f.r * 3;
      ctx.fillStyle = 'rgba(255,255,255,' + f.opacity + ')';
      ctx.fill();
    });
  }

  function stopSnow(){
    if(rafId){ cancelAnimationFrame(rafId); rafId = null; }
    if(ctx && canvas) ctx.clearRect(0, 0, canvas.width, canvas.height);
  }

  function evaluate(){
    if(!isChristmasWindow()) { stopSnow(); return; }
    var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    if(isDark){ startSnow(); } else { stopSnow(); } // Hellmodus: bewusst inaktiv
  }

  document.addEventListener('DOMContentLoaded', function(){
    evaluate();
    var themeBtn = document.getElementById('theme-toggle');
    if(themeBtn) themeBtn.addEventListener('click', function(){
      setTimeout(evaluate, 0); // nach dem eigentlichen Theme-Wechsel neu pruefen
    });
  });
})();

/* ---------- Homepage: "Weiterlesen"-Button fuer den Lead-Absatz (nur Mobil) ----------
   Auf dem Handy klemmt der Lead-Text per CSS auf 4 Zeilen (siehe
   .lead-toggle/.is-expanded in style.css). Dieser Button klappt ihn bei
   Bedarf auf. Existiert der Button nicht (jede andere Seite ausser
   index.html), passiert einfach nichts -- kein Fehler. */
(function(){
  document.addEventListener('DOMContentLoaded', () => {
    const p = document.getElementById('hero-lead');
    const btn = document.getElementById('lead-toggle');
    if(!p || !btn) return;
    function isEn(){ return document.documentElement.getAttribute('lang') === 'en'; }
    function syncLabel(){
      const expanded = p.classList.contains('is-expanded');
      const de = expanded ? 'Weniger anzeigen' : 'Weiterlesen';
      const en = expanded ? 'Show less' : 'Read more';
      btn.textContent = isEn() ? en : de;
      btn.setAttribute('data-en', en);
    }
    btn.addEventListener('click', () => {
      const expanded = p.classList.toggle('is-expanded');
      btn.setAttribute('aria-expanded', expanded);
      syncLabel();
    });
    // Gleiche Cache-Falle wie beim Einfache-Sprache-Schalter: der generische
    // DE/EN-Mechanismus cached data-de beim ersten Sprachwechsel und wuerde
    // danach eingefrorene Labels zeigen, wenn sich der Aufklapp-Zustand
    // zwischendurch geaendert hat. Nach jedem Sprachwechsel aktiv neu setzen.
    const langBtn = document.getElementById('lang-toggle');
    if(langBtn) langBtn.addEventListener('click', syncLabel);
  });
})();

/* ============================================================
   V500 — Mobile Icon Ladder
   V510: Schwellenwert rein breitenbasiert (max-width:900px), nicht mehr
   an "pointer:coarse" gekoppelt. Dadurch loest die Leiter auch bei
   Maus-Bedienung aus, sobald das Fenster/der Zoom die 900px-Schwelle
   unterschreitet -- praktisch zum Testen per Fenster-Groesse ziehen,
   ohne ein echtes Touch-Geraet zu brauchen. Erste Klick/Tap-Aktion
   prueft die Breite frisch bei jeder Interaktion, kein Resize-Listener
   noetig. Normales Klick-/Touch-Verhalten oberhalb 900px unveraendert.
   ============================================================ */
(function(){
  function initMobileIconLadder(){
    const controls = document.querySelector('.header-controls');
    if(!controls || controls.dataset.frLadderBound === '1') return;
    controls.dataset.frLadderBound = '1';

    function isNarrow(){
      if(document.documentElement.classList.contains('fr-force-ladder')) return true;
      return window.matchMedia && window.matchMedia('(max-width:900px)').matches;
    }
    function isDesktopForce(){
      return document.documentElement.classList.contains('fr-force-ladder') &&
        window.matchMedia && window.matchMedia('(min-width:901px)').matches;
    }

    let open = false;
    let pointerId = null;
    let startY = 0;
    let lastY = 0;
    let selected = null;
    let moved = false;

    function items(){
      return Array.from(controls.children).filter(el => {
        if(el.classList.contains('alert-test-btn')) return false;
        if(el.hidden) return false;
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      });
    }
    function clearSelected(){
      items().forEach(el => el.classList.remove('fr-ladder-selected'));
      selected = null;
    }
    function selectByY(y){
      const els = items();
      if(!els.length) return;
      let best = els[0], bestDist = Infinity;
      els.forEach(el => {
        const r = el.getBoundingClientRect();
        const d = Math.abs(y - (r.top + r.height/2));
        if(d < bestDist){ best = el; bestDist = d; }
      });
      if(selected !== best){
        clearSelected();
        selected = best;
        selected.classList.add('fr-ladder-selected');
      }
    }
    /* V515 -- header.site hat backdrop-filter:blur() gesetzt. Das erzeugt
       per Spezifikation einen neuen Bezugsrahmen fuer position:fixed-
       Nachfahren (wie bei transform), wodurch top:50% nicht relativ zum
       echten Viewport, sondern relativ zur kurzen Sticky-Header-Box
       berechnet wurde -- die Leiter "klebte" dadurch oben. Fix: Beim
       Oeffnen wird .header-controls per JS an document.body angehaengt
       (damit ausserhalb jedes backdrop-filter-Vorfahren), beim Schliessen
       exakt an die urspruengliche Stelle im DOM zurueckgestellt. */
    const originalParent = controls.parentNode;
    const originalNextSibling = controls.nextSibling;

    function openLadder(y){
      open = true;
      document.body.appendChild(controls);
      controls.classList.add('fr-touch-ladder');
      document.documentElement.classList.add('fr-mobile-ladder-open');
      selectByY(y);
    }
    function closeLadder(){
      open = false;
      pointerId = null;
      controls.classList.remove('fr-touch-ladder');
      document.documentElement.classList.remove('fr-mobile-ladder-open');
      clearSelected();
      if(originalNextSibling && originalNextSibling.parentNode === originalParent){
        originalParent.insertBefore(controls, originalNextSibling);
      } else {
        originalParent.appendChild(controls);
      }
    }

    /* Mobile-Leiter erzwingen (Test-Schalter, V512/V513). Rein zum Testen
       auf jedem Bildschirm, unabhaengig von echter Fensterbreite/Zoom.
       V513: oeffnet die Leiter sofort beim Klick (statt erst beim naechsten
       Icon-Klick zu wirken) -- ausgewaehlt wird das Icon naechst der
       vertikalen Bildschirmmitte, da kein echter Zeiger-Y-Wert vorliegt.
       Kein localStorage -- bewusst nur fuer die laufende Sitzung. */
    /* Idle-Hinweis-Pille (V514) ist jetzt klickbar (V517): oeffnet die
       Leiter direkt an der Klickposition, wie ein normaler Tap auf die
       Leiter selbst. */
    const hint = document.querySelector('.fr-ladder-hint');
    if(hint){
      hint.addEventListener('click', (e) => {
        if(!isNarrow()) return;
        openLadder(e.clientY);
      });
    }

    const forceBtn = document.getElementById('force-ladder-toggle');
    if(forceBtn){
      forceBtn.addEventListener('click', () => {
        const root = document.documentElement;
        const turningOn = !root.classList.contains('fr-force-ladder');
        root.classList.toggle('fr-force-ladder', turningOn);
        forceBtn.setAttribute('aria-pressed', turningOn);
        forceBtn.title = turningOn ? 'Mobile-Leiter-Test ausschalten' : 'Mobile-Leiter-Test einschalten';
        if(turningOn){
          /* V525: Im Desktop-Force-Test bleibt die normale Header-Leiste
             zunaechst voll funktionsfaehig. Die neue Leiter wird bewusst
             ausschliesslich ueber die blaue Rand-Pille geoeffnet. */
        } else if(open){
          closeLadder();
        }
      });
    }
    function activateSelected(){
      if(!selected) return;
      const el = selected;
      // A composite font stepper is selected as one ladder item; a flick
      // confirms the + action, which is the most useful mobile default.
      if(el.classList.contains('font-stepper')){
        const plus = el.querySelector('#font-stepper-plus');
        if(plus) plus.click();
      } else if(typeof el.click === 'function') {
        el.click();
      }
      // Keep the visual confirmation very brief, then return to normal header.
      el.classList.add('fr-ladder-confirmed');
      setTimeout(() => {
        el.classList.remove('fr-ladder-confirmed');
        closeLadder();
      }, 110);
    }

    controls.addEventListener('pointerdown', function(e){
      if(!isNarrow()) return;
      /* V524: Auf breiten Desktop-Bildschirmen bleibt die normale Header-
         Icon-Leiste die primaere Bedienung. Im Force-Test wird die Leiter
         deshalb NICHT durch einen Klick auf Kontrast, Theme, Suche usw.
         geoeffnet. Sie kommt ausschliesslich ueber die blaue Rand-Pille.
         Sobald die Leiter bereits offen ist, greift die normale Gestenlogik
         wieder und die Header-Leiste ist aus dem Header entfernt. */
      if(!open && isDesktopForce()) return;
      /* V522: Der Hamburger ist ein echtes Leiter-Feld. Ein normaler Tap
         auf dieses Feld darf weiterhin direkt den bestehenden nav-toggle-
         Click ausloesen; deshalb wird der native Button-Click hier nicht
         von der Leiter-Gestenlogik abgefangen. */
      const navToggle = e.target.closest && e.target.closest('.nav-toggle');
      if(navToggle){
        /* Direktes Hamburger-Tippen bleibt immer Direktzugriff auf das
           Hauptmenue. Auch in der bereits geoeffneten Leiter darf der
           native Click durchgereicht werden. */
        return;
      }
      if(!open){
        e.preventDefault();
        pointerId = e.pointerId;
        startY = lastY = e.clientY;
        moved = false;
        openLadder(e.clientY);
        try{ controls.setPointerCapture(pointerId); }catch(_){ }
      } else {
        pointerId = e.pointerId;
        startY = lastY = e.clientY;
        moved = false;
        selectByY(e.clientY);
        e.preventDefault();
      }
    }, {passive:false});

    controls.addEventListener('pointermove', function(e){
      if(!open || pointerId !== e.pointerId) return;
      e.preventDefault();
      lastY = e.clientY;
      if(Math.abs(lastY - startY) > 7) moved = true;
      selectByY(lastY);
    }, {passive:false});

    controls.addEventListener('pointerup', function(e){
      if(!open || pointerId !== e.pointerId) return;
      e.preventDefault();
      const dy = e.clientY - startY;
      pointerId = null;
      // A deliberate vertical flick confirms. A simple tap leaves the ladder
      // open so the user can continue selecting without precision tapping.
      if(Math.abs(dy) >= 24 && moved){
        activateSelected();
      }
    }, {passive:false});

    controls.addEventListener('pointercancel', function(){
      if(open) closeLadder();
    });

    // ESC schliesst die Leiter ebenfalls. Das ist fuer Tastaturbedienung
    // und Assistenztechnik die eindeutige Rueckkehr zur normalen Ansicht.
    document.addEventListener('keydown', function(e){
      if(e.key === 'Escape' && open){
        e.preventDefault();
        closeLadder();
      }
    });

    // Tap outside the fixed ladder closes it without triggering page actions.
    document.addEventListener('pointerdown', function(e){
      if(!open) return;
      if(!controls.contains(e.target) && (e.pointerType === 'touch' || e.pointerType === 'pen')){
        closeLadder();
      }
    }, {passive:true});

    window.addEventListener('resize', function(){
      if(open) selectByY(lastY || window.innerHeight/2);
    });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initMobileIconLadder);
  } else {
    initMobileIconLadder();
  }
})();


document.addEventListener('DOMContentLoaded', () => { frInitYouthEasterEggSwitch(); frInitQuizTimerSlider(); frApplyConstants(); frApplySnippets(); });
